int msync(void *addr, size_t length, int flags);

void *map_start = (void*)0xDEADBEEF;
size_t map_len = 4096;

// Synchronous flush (wait for write to complete)
if (msync(map_start, map_len, MS_SYNC) == -1) {
    /* Handle error */
}

// Asynchronous flush (return immediately)
msync(map_start, map_len, MS_ASYNC);

// Synchronous flush AND invalidate cached data
msync(map_start, map_len, MS_SYNC | MS_INVALIDATE);

